-- 016: velocity limits per role (defaults) or per account (overrides): per transaction, daily and monthly.
CREATE TABLE pp_transaction_limits (
    id                NUMBER(19) GENERATED BY DEFAULT AS IDENTITY,
    scope             VARCHAR2(10 CHAR) NOT NULL,
    role_code         VARCHAR2(30 CHAR),
    account_id        NUMBER(19),
    service_code      VARCHAR2(30 CHAR) NOT NULL,
    min_txn           NUMBER(19,2) NOT NULL,
    max_txn           NUMBER(19,2) NOT NULL,
    daily_amount      NUMBER(19,2) NOT NULL,
    monthly_amount    NUMBER(19,2) NOT NULL,
    daily_count       NUMBER(10) NOT NULL,
    monthly_count     NUMBER(10) NOT NULL,
    valid_until       TIMESTAMP,
    set_by_account_id NUMBER(19),
    updated_at        TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_pp_limits PRIMARY KEY (id),
    CONSTRAINT uq_pp_limits_scope UNIQUE (scope, role_code, account_id, service_code)
);

